wishlist_items: customer_id, product_id, added_at; unique (customer_id, product_id)
export type WishlistItem = { productId: string; addedAt: Date };
const lists = new Map<string, WishlistItem[]>();
export function save(customerId: string, productId: string, at: Date = new Date()): void {
  const list = lists.get(customerId) ?? [];
  if (!list.some((item) => item.productId === productId)) list.push({ productId, addedAt: at });
  lists.set(customerId, list);
}
export function list(customerId: string): string[] { return (lists.get(customerId) ?? []).map((item) => item.productId); }
export function _reset(): void { lists.clear(); }
